// Import the Verus prelude
use verus::prelude::*;

verus! {

    /// Given two sorted, non-empty arrays `a` and `b` of signed 8-bit integers,
    /// with lengths `n_a` and `n_b` respectively, and given two 1-based
    /// selection indices `k` (into `a`) and `m` (from the end of `b`),
    /// return "YES" exactly when
    ///    a[k-1] < b[n_b - m]
    /// otherwise return "NO".
    ///
    /// Preconditions (requires):
    ///  1) n_a >= 1, n_b >= 1
    ///  2) a.len() == n_a as usize, b.len() == n_b as usize
    ///  3) 1 <= k <= n_a, 1 <= m <= n_b
    ///  4) Both `a` and `b` are sorted in non-decreasing order.
    ///
    /// Postcondition (ensures):
    ///   (a[k-1] < b[n_b - m])  <==>  (result == "YES")
    ///
    pub fn solve(
        n_a: i8,
        n_b: i8,
        k: i8,
        m: i8,
        a: Vec<i8>,
        b: Vec<i8>,
    ) -> &'static str
        // 1) Sizes are positive
        requires n_a >= 1
        requires n_b >= 1
        // 2) Vector lengths match the declared sizes
        requires a.len() == (n_a as usize)
        requires b.len() == (n_b as usize)
        // 3) Selection indices are in range
        requires 1 <= k && k <= n_a
        requires 1 <= m && m <= n_b
        // 4) Arrays are sorted non-decreasingly
        requires forall |i: usize| i + 1 < a.len() ==> a[i] <= a[i+1]
        requires forall |i: usize| i + 1 < b.len() ==> b[i] <= b[i+1]
        // Postcondition tying the returned string to the comparison
        ensures ( a[((k - 1) as usize)] < b[((n_b - m) as usize)] )
                == (result == "YES")
    {
        // Compute zero-based indices safely (guaranteed by the `requires` above)
        let ia: usize = (k - 1) as usize;
        let ib: usize = (n_b - m) as usize;

        if a[ia] < b[ib] {
            "YES"
        } else {
            "NO"
        }
    }
}